import{_ as i,C as r,o as n,c as h,j as e,a as d,E as o,a5 as c}from"./chunks/framework.Dep_XxFZ.js";const P=JSON.parse('{"title":"标签","description":"","frontmatter":{},"headers":[],"relativePath":"components/tag.md","filePath":"components/tag.md","lastUpdated":1787363843000}'),s={name:"components/tag.md"},b={id:"标签",tabindex:"-1"};function p(g,t,u,x,f,q){const l=r("Badge"),a=r("XhDemo");return n(),h("div",null,[e("h1",b,[t[0]||(t[0]=d("标签 ",-1)),o(l,{type:"info",text:"tag"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#标签","aria-label":'Permalink to "标签 <Badge type="info" text="tag" />"'},"​",-1))]),t[3]||(t[3]=c('<p>告诉你这是什么：一个分类、一项技能、一个筛选条件。它承载实体身份，可以被摘掉。 标签说的是「它是什么」，不是「有事情发生了」——后者是<a href="./badge">徽标</a>的活。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>一条记录挂着的若干分类、技能、关键词。</li><li>已生效的筛选条件，用户可以逐条摘掉。</li><li>需要用户看清&quot;这是什么&quot;并能把它移除的任何短文本。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>提醒用户注意某个东西——未读数、小红点、在线状态：用<a href="./badge">徽标</a>，它附着在别的元素上、不接交互。</li><li>用户要在几个互斥选项里挑一个：用<a href="./radio-group">单选组</a>或<a href="./toggle-group">切换按钮组</a>。</li><li>用户要自己输入并累积多个值：用<a href="./tags-input">标签输入</a>，它自带输入框与增删逻辑。</li><li>是一整条页面级提示：用<a href="./alert">警告提示</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>形态 · 语气 · 尺寸三轴与其余组件同源。</li><li><code>closable</code> 给出关闭钮，显隐可受控（<code>open</code> / <code>defaultOpen</code> / <code>open-change</code>）。</li><li><code>disabled</code> 让标签留在原地但摘不掉，宽度不会因禁用而跳变。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一个标签就是 root 加一段 label 文字；不写 closable 就没有关闭钮</p>',10)),o(a,{src:"tag/01-basic"}),t[4]||(t[4]=e("h3",{id:"形态",tabindex:"-1"},[d("形态 "),e("a",{class:"header-anchor",href:"#形态","aria-label":'Permalink to "形态"'},"​")],-1)),t[5]||(t[5]=e("p",null,"variant 决定颜色怎么用：实心填底、淡色填底、只描边",-1)),o(a,{src:"tag/02-variant"}),t[6]||(t[6]=e("h3",{id:"语气",tabindex:"-1"},[d("语气 "),e("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[7]||(t[7]=e("p",null,"tone 决定用哪族颜色；语气只换色相，形态与尺寸不受影响",-1)),o(a,{src:"tag/03-tone"}),t[8]||(t[8]=e("h3",{id:"可关闭",tabindex:"-1"},[d("可关闭 "),e("a",{class:"header-anchor",href:"#可关闭","aria-label":'Permalink to "可关闭"'},"​")],-1)),t[9]||(t[9]=e("p",null,"closable 给出关闭钮；open 受控时去留由宿主决定，可访问名逐枚带上标签文字，摘掉一枚后焦点交给下一枚",-1)),o(a,{src:"tag/04-closable"}),t[10]||(t[10]=e("h3",{id:"禁用",tabindex:"-1"},[d("禁用 "),e("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[11]||(t[11]=e("p",null,"disabled 让标签留在原地却摘不掉：关闭钮仍占着位置，标签宽度不因禁用跳变",-1)),o(a,{src:"tag/05-disabled"}),t[12]||(t[12]=e("h3",{id:"尺寸",tabindex:"-1"},[d("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[13]||(t[13]=e("p",null,"size 只改内边距、间距与字号，不写就是缺省档；关闭钮的命中区不跟着缩",-1)),o(a,{src:"tag/06-size"}),t[14]||(t[14]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-tag&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTagCloseTrigger</code> <code>XhTagLabel</code> <code>XhTagRoot</code></td></tr><tr><td>组合式函数</td><td><code>useTag</code></td></tr><tr><td>状态机</td><td><code>tagMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/tag.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;tag&quot;</code>：<strong><code>root</code></strong> · <code>label</code> · <code>close-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>variant</code></td><td><code>TagVariant</code></td><td></td><td>形态：solid / subtle / outline，决定颜色怎么用。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>closable</code></td><td><code>boolean</code></td><td></td><td>是否给出关闭钮，默认 false。false 时该钮同时被禁用与收起。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>标签禁用：关闭钮不可用，点击不改显隐。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td>受控显隐；缺省该 prop 即非受控。</td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td>非受控初始显隐，默认显示。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: TagOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TagTranslations&gt;</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>TagOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>CLOSE</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSED</code></p><p><strong>判据</strong>：<code>isOpenControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useTag</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>closable</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCloseTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus 在 close-trigger 上，且 closable 且未禁用</td><td>收起标签并通知 open=false；关闭钮是原生 button，这两个键由平台翻成 click</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>close-trigger</code></td><td><code>aria-label</code></td><td>props.translations.close</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/tag.css</code> 按部件选择：<code>[data-scope=&quot;tag&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>close-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-tag-bg</code> · <code>--xh-tag-bg-disabled</code> · <code>--xh-tag-border</code> · <code>--xh-tag-border-disabled</code> · <code>--xh-tag-close-bg-active</code> · <code>--xh-tag-close-bg-hover</code> · <code>--xh-tag-close-fg</code> · <code>--xh-tag-close-radius</code> · <code>--xh-tag-close-size</code> · <code>--xh-tag-fg</code> · <code>--xh-tag-font-size</code> · <code>--xh-tag-font-weight</code> · <code>--xh-tag-gap</code> · <code>--xh-tag-icon-size</code> · <code>--xh-tag-px</code> · <code>--xh-tag-py</code> · <code>--xh-tag-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>一排标签用<a href="./flex">弹性布局</a>排开。</li><li>标签里的图元用<a href="./icon">图标</a>。</li><li>文字过长时配<a href="./ellipsis">文本省略</a>，或直接让皮肤截断。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>关闭钮的可访问名要带上标签文字：默认只念 Remove，一屏十个标签听起来一模一样。逐实例传 <code>translations.close</code> 写成&quot;移除 前端&quot;。</li><li>摘掉一枚之后要把焦点交出去：标签是成排出现的，被摘的那一枚带着焦点一起消失，焦点会掉回页面开头，键盘与读屏用户每摘一次就丢一次位置。交给顶上来的那一枚的关闭钮，一枚不剩就交给列表容器或&quot;还原&quot;钮。组件不替宿主决定去留，这件事也就只能宿主自己接。</li><li>摘掉一个标签之后要有回退路径，否则用户误点就再也加不回来。</li><li>标签文字尽量短：它是身份标记，不是句子。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把标签当按钮用：整块可点却没有按钮语义，键盘用户根本按不到。</li><li>一屏铺满高饱和度的实心标签：全都在喊，等于都没喊。</li><li>用颜色单独表达含义：色觉障碍的用户分不出来，文字本身要说清楚。</li></ul>',45))])}const T=i(s,[["render",p]]);export{P as __pageData,T as default};
